linked_items = frappe.get_all('Maintenance Schedule Item', filters={'sales_order': doc.name}, fields=['parent'])
#linked_items = frappe.get_all('Delivery Note Item', filters={'against_sales_order': doc.name}, fields=['parent'])
linked_maintenance = {item.parent for item in linked_items}
frappe.flags.ignore_permissions = True
for dn_name in linked_maintenance:
    if frappe.db.exists("Maintenance Schedule", dn_name):
        dn = frappe.get_doc("Maintenance Schedule", dn_name)
        # Check if the Delivery Note is submitted and then cancel it
        if dn.docstatus == 1:
            dn.cancel()
            frappe.delete_doc("Maintenance Schedule", dn.name, ignore_permissions=True)

frappe.flags.ignore_permissions = False

# Script corrigé et sécurisé

inactive_statuses = ["Draft", "Cancelled", "Closed", "On Hold"]
is_active_order = doc.status not in inactive_statuses

frappe.flags.ignore_permissions = True

def is_locked_pe(paid_to, mode, ptt):
    locked_bank = ["STE430127B - Zitouna - A&S", "Chèques sans provision - A&S", "Traite Bancaire sans provision - A&S"]
    partner = ["Economiq Aqua Solution - A&S", "Ayman Fourati - A&S"]
    if paid_to in locked_bank:
        return True
    if paid_to in partner:
        return False
    if mode == "Espèces":
        default = "Espèces - A&S"
    elif mode == "Chèque":
        default = "Chèques - A&S"
    elif mode == "Dette non payée":
        default = "Livraison Aramex - A&S" if ptt == "Livraison Aramex" else "Dettes - A&S"
    elif mode == "Traite bancaire LC":
        default = "Traite Bancaire - A&S"
    elif mode == "Retenue a la source vente":
        default = "Avance  impôt société - A&S"
    elif mode == "Perte de paiement":
        default = "Perte de non paiement - A&S"
    else:
        default = "STE430127B - Zitouna - A&S"
    return paid_to != default

def row_fingerprint(term):
    src = "|".join([
        "%.3f" % frappe.utils.flt(term.payment_amount, 3),
        term.mode_of_payment or "",
        term.custom_banque or "",
        term.custom__n_chèque__transaction or "",
        str(frappe.utils.getdate(term.due_date)) if term.due_date else "",
    ])
    return frappe.utils.sha256_hash(src)


# ------------------------------------------------------------
# 1) Génération de l'échéancier de maintenance
# ------------------------------------------------------------

if is_active_order and frappe.utils.cint(doc.custom_generate_maintenace_schedule) == 1:

    maintenance_item_groups = [
        "Osmoseur Industriel",
        "Osmoseur Domestique",
        "Osmoseur Commercial",
        "Osmoseur Bi-osmose",
        "Adoucisseur",
        "Porte filtre"
    ]

    quarterly_groups = [
        "Osmoseur Industriel",
        "Osmoseur Commercial",
        "Osmoseur Bi-osmose",
        "Porte filtre",
        "Adoucisseur"
    ]

    maintenance_schedule = frappe.new_doc("Maintenance Schedule")
    maintenance_schedule.customer = doc.customer
    maintenance_schedule.transaction_date = doc.delivery_date or doc.transaction_date
    maintenance_schedule.generate_events = False

    for item in doc.items:
        if item.item_group in maintenance_item_groups:

            start_date = doc.delivery_date or doc.transaction_date
            end_date = frappe.utils.add_years(start_date, 3)

            if item.item_group in quarterly_groups:
                periodicity = "Quarterly"
                no_of_visits = 20
            else:
                periodicity = "Half Yearly"
                no_of_visits = 10

            maintenance_schedule.append("items", {
                "item_code": item.item_code,
                "item_name": item.item_name,
                "start_date": start_date,
                "end_date": end_date,
                "sales_order": doc.name,
                "periodicity": periodicity,
                "no_of_visits": no_of_visits,
                "sales_person": "Équipe des Ventes"
            })

    # Important : ne pas créer un Maintenance Schedule vide
    if len(maintenance_schedule.items) > 0:
        maintenance_schedule.insert(ignore_permissions=True)
        maintenance_schedule.submit()

        doc.custom_generate_maintenace_schedule = 0
        doc.custom_maintenace_origine = 1

        frappe.msgprint(
            "Échéancier d'Entretien: "
            + maintenance_schedule.name
            + " est créé"
        )
    else:
        doc.custom_generate_maintenace_schedule = 0
        frappe.msgprint(
            "Aucun article éligible à la maintenance trouvé dans cette commande."
        )


# ------------------------------------------------------------
# 2) Vérification et suppression des anciens paiements
# ------------------------------------------------------------

if is_active_order:

    if (
        frappe.utils.cint(doc.custom_maintenace_origine) != 1
        and frappe.utils.cint(doc.custom_outil_de_paiement) != 1
    ):

        payment_sum = 0
        line_no = 0

        for ipay in doc.payment_schedule:
            line_no = line_no + 1
            payment_sum = payment_sum + frappe.utils.flt(ipay.payment_amount)

            if ipay.mode_of_payment == "Chèque":

                cheque_no = ipay.custom__n_chèque__transaction

                if cheque_no is None:
                    cheque_no = ""

                cheque_no = str(cheque_no).strip()

                if cheque_no == "":
                    frappe.throw(
                        "Le Numero du chèque de la ligne "
                        + str(line_no)
                        + " est vide"
                    )

                elif frappe.utils.cint(cheque_no) == 0 or len(cheque_no) != 7:
                    frappe.throw(
                        "Le Numero : "
                        + cheque_no
                        + " du chèque de la ligne "
                        + str(line_no)
                        + " n'est pas valide"
                    )

                bank = ipay.custom_banque

                if bank is None:
                    bank = ""

                bank = str(bank).strip()

                if bank == "":
                    frappe.throw(
                        "Merci de selectionner la banque du chèque de la ligne "
                        + str(line_no)
                        + " !!!"
                    )

        total = frappe.utils.flt(doc.rounded_total)

        if frappe.utils.cint(doc.disable_rounded_total) == 1:
            total = frappe.utils.flt(doc.grand_total)

        if abs(round(payment_sum, 3) - round(total, 3)) >= 0.1:
            frappe.throw(
                "Le Total des paiements est different de la valeur TTC de la commande"
            )

        row_fp_by_uid = {}
        for term in doc.payment_schedule:
            row_fp_by_uid[term.custom_row_uid] = row_fingerprint(term)

        payments_to_delete = []

        # ------------------------------------------------------------
        # Paiements liés directement à la Sales Order
        # Correction : utiliser Payment Entry Reference
        # ------------------------------------------------------------

        payment_refs = frappe.get_all(
            "Payment Entry Reference",
            filters={
                "reference_doctype": "Sales Order",
                "reference_name": doc.name,
                "parenttype": "Payment Entry"
            },
            fields=["parent"]
        )

        for ref in payment_refs:
            if ref.parent and ref.parent not in payments_to_delete:
                pe_info = frappe.db.get_value("Payment Entry", ref.parent, ["paid_to", "mode_of_payment", "custom_source_row_uid", "custom_source_fingerprint"], as_dict=True)
                if pe_info and is_locked_pe(pe_info.paid_to, pe_info.mode_of_payment, doc.payment_terms_template):
                    continue
                if pe_info and pe_info.custom_source_row_uid in row_fp_by_uid and row_fp_by_uid[pe_info.custom_source_row_uid] == pe_info.custom_source_fingerprint:
                    continue
                payments_to_delete.append(ref.parent)

        # ------------------------------------------------------------
        # Factures liées à la Sales Order
        # Correction : chercher via Sales Invoice Item
        # ------------------------------------------------------------

        invoice_rows = frappe.get_all(
            "Sales Invoice Item",
            filters={
                "sales_order": doc.name
            },
            fields=["parent"]
        )

        unique_invoices = []

        for row in invoice_rows:
            if row.parent and row.parent not in unique_invoices:
                unique_invoices.append(row.parent)

        for invoice_name in unique_invoices:

            if not frappe.db.exists("Sales Invoice", invoice_name):
                continue

            inv = frappe.get_doc("Sales Invoice", invoice_name)

            if inv.docstatus != 1:
                continue

            advances = inv.advances or []

            for advance in advances:

                payment_entry_name = advance.reference_name

                if not payment_entry_name:
                    continue

                remarks = advance.remarks

                if remarks is None:
                    remarks = ""

                remarks = str(remarks)

                words = remarks.split()

                matches = []

                for word in words:
                    clean_word = word.strip(" ,.;:()[]{}")

                    if clean_word.startswith("SAL-ORD") or clean_word.startswith("WEB"):
                        if clean_word not in matches:
                            matches.append(clean_word)

                # Correction principale :
                # Avant, le script faisait matches[0] même si matches était vide.
                is_related_to_this_order = False

                if doc.name in remarks:
                    is_related_to_this_order = True
                else:
                    for sales_order_ref in matches:
                        if doc.name in sales_order_ref:
                            is_related_to_this_order = True

                if not is_related_to_this_order:
                    continue

                if not frappe.db.exists("Payment Entry", payment_entry_name):
                    continue

                payment_entry_doc = frappe.get_doc(
                    "Payment Entry",
                    payment_entry_name
                )

                if is_locked_pe(payment_entry_doc.paid_to, payment_entry_doc.mode_of_payment, doc.payment_terms_template):
                    continue

                if payment_entry_doc.custom_source_row_uid in row_fp_by_uid and row_fp_by_uid[payment_entry_doc.custom_source_row_uid] == payment_entry_doc.custom_source_fingerprint:
                    continue

                try:
                    inv.delink_advance_entries(payment_entry_doc.name)
                except Exception:
                    pass

                if payment_entry_doc.name not in payments_to_delete:
                    payments_to_delete.append(payment_entry_doc.name)

        # ------------------------------------------------------------
        # Suppression des anciens paiements
        # ------------------------------------------------------------

        for pe_name in payments_to_delete:

            if not frappe.db.exists("Payment Entry", pe_name):
                continue

            payment_entry_doc = frappe.get_doc("Payment Entry", pe_name)

            frappe.msgprint("Suppression de l'ancien paiement : " + pe_name)

            payment_entry_doc.flags.ignore_links = True
            payment_entry_doc.flags.ignore_permissions = True

            if payment_entry_doc.docstatus == 1:
                payment_entry_doc.cancel()

            frappe.delete_doc(
                "Payment Entry",
                payment_entry_doc.name,
                ignore_permissions=True
            )

        doc.advance_paid = 0.0
